# Let's write a small C# program to read the binlog
mkdir -p /tmp/binlog-reader && cd /tmp/binlog-reader && cat > binlog-reader.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.405" />
  </ItemGroup>
</Project>
EOF
cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

// Collect all errors
var errors = new List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(error => {
    var project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.ToString(), error.File ?? "", error.LineNumber));
});

// Group by project
var byProject = errors.GroupBy(e => e.project).OrderBy(g => g.Key);
Console.WriteLine($"Total errors: {errors.Count}\n");

foreach (var group in byProject) {
    Console.WriteLine($"--- Project: {group.Key} ---");
    foreach (var e in group) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
    Console.WriteLine();
}

// Also show warnings that might be relevant
Console.WriteLine("\n=== KEY WARNINGS ===");
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(w => {
    var project = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    if (w.Code != null && (w.Code.StartsWith("NU") || w.Code.StartsWith("MSB")))
        warnings.Add((project, w.Code, w.ToString()));
});
foreach (var w in warnings.Take(30)) {
    Console.WriteLine($"  [{w.code}] ({w.project}) {w.message}");
}
EOF
