using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Show all projects and their references
Console.WriteLine("=== ALL PROJECTS ===");
var projects = new HashSet<string>();
build.VisitAllChildren<Project>(p => {
    if (projects.Add(p.Name)) {
        Console.WriteLine($"  {p.Name}");
    }
});

// Look at items/metadata for package refs
Console.WriteLine("\n=== LOOKING FOR PACKAGE REFERENCES ===");
build.VisitAllChildren<Project>(p => {
    if (!p.Name.Contains("Services")) return;
    p.VisitAllChildren<AddItem>(item => {
        if (item.Name == "PackageReference") {
            Console.WriteLine($"  {p.Name} -> PackageReference: {item.Title}");
        }
    });
    p.VisitAllChildren<NamedNode>(node => {
        if (node.Name == "PackageReference" && node.ToString().Contains("Newtonsoft")) {
            Console.WriteLine($"  Found Newtonsoft ref: {node}");
        }
    });
});

// Look for restore issues
Console.WriteLine("\n=== RESTORE MESSAGES ===");
build.VisitAllChildren<Message>(m => {
    var msg = m.Text ?? "";
    if (msg.Contains("Newtonsoft") || msg.Contains("NU1")) {
        Console.WriteLine($"  {msg.Substring(0, Math.Min(200, msg.Length))}");
    }
});
EOF
